messages.content:
Generate a product catalogue for a self-storage and moving supplies shop as JSON.

Return exactly 1030 records in one JSON array and nothing else: no explanation before or after it and no code fences. Every record must validate against this JSON Schema:

{
 "$schema": "https://json-schema.org/draft/2020-12/schema",
 "type": "object",
 "additionalProperties": false,
 "required": [
  "id",
  "sku",
  "name",
  "category",
  "price_cents",
  "in_stock",
  "tags",
  "dimensions_mm",
  "supplier"
 ],
 "properties": {
  "id": {
   "type": "integer",
   "minimum": 1
  },
  "sku": {
   "type": "string",
   "pattern": "^[A-Z]{3}-[0-9]{5}$"
  },
  "name": {
   "type": "string",
   "minLength": 3,
   "maxLength": 60
  },
  "category": {
   "type": "string",
   "enum": [
    "tools",
    "storage",
    "lighting",
    "outdoor",
    "kitchen",
    "electrical",
    "garden",
    "safety"
   ]
  },
  "price_cents": {
   "type": "integer",
   "minimum": 1,
   "maximum": 10000000
  },
  "in_stock": {
   "type": "boolean"
  },
  "tags": {
   "type": "array",
   "minItems": 1,
   "maxItems": 4,
   "uniqueItems": true,
   "items": {
    "type": "string",
    "pattern": "^[a-z][a-z0-9-]{1,19}$"
   }
  },
  "dimensions_mm": {
   "type": "object",
   "additionalProperties": false,
   "required": [
    "length",
    "width",
    "height"
   ],
   "properties": {
    "length": {
     "type": "integer",
     "minimum": 1,
     "maximum": 100000
    },
    "width": {
     "type": "integer",
     "minimum": 1,
     "maximum": 100000
    },
    "height": {
     "type": "integer",
     "minimum": 1,
     "maximum": 100000
    }
   }
  },
  "supplier": {
   "type": "object",
   "additionalProperties": false,
   "required": [
    "name",
    "country"
   ],
   "properties": {
    "name": {
     "type": "string",
     "minLength": 2,
     "maxLength": 60
    },
    "country": {
     "type": "string",
     "pattern": "^[A-Z]{2}$"
    }
   }
  }
 }
}

Further rules:
- The id values are 1 to 1030, in order.
- Every sku is unique.
- Make the products varied and realistic for a self-storage and moving supplies shop; do not repeat a name.
- Write each record compactly on its own line.
